1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { hasAreaAccess } from "./staff-grants";
9	import { writeTicketReply, createTicketCore } from "./reply-core";
10	import { mirrorNewTicketToDiscord, mirrorTicketReplyToDiscord, setDiscordThreadArchived } from "./discord-bridge";
11	import { validateTicketAttachmentBytes, MAX_TICKET_ATTACHMENT_BYTES } from "./ticket-attachment";
12	
13	/**
14	 * SUPPORT-ROLE ENFORCEMENT (2026-07-27 admin audit).
15	 *
16	 * `lib/rbac.ts` grants the `support` area to SUPPORT and ADMIN, `/admin/support`
17	 * and `/admin/support/[id]` both gate on `requireArea("support")`, and the admin
18	 * layout renders the desk in a SUPPORT agent's sidebar. Every WRITE behind those
19	 * pages, however, still required ADMIN:
20	 *
21	 *   - `setTicketPriority` called `requireAdmin()`. `PrioritySelect` does not
22	 *     catch, so a SUPPORT agent picked "Urgent", the throw vanished into an
23	 *     unhandled transition, and the `<select>` (uncontrolled, `defaultValue`)
24	 *     kept showing the new value. The control reported success and did nothing.
25	 *   - `setTicketStatus` and `replyTicket` applied the CUSTOMER ownership test
26	 *     (`ticket.userId !== user.id && role !== "ADMIN"`), so a SUPPORT agent could
27	 *     neither close nor answer a ticket that was not their own — i.e. any ticket.
28	 *
29	 * So the entire job of the SUPPORT role was a read-only page with three controls
30	 * that silently refused. `lib/actions-chat.ts` — the other half of the same area —
31	 * has always gated correctly on `requireArea("support")`; the ticket desk simply
32	 * was never updated when RBAC landed. These now use the same rule. No role gains
33	 * anything `lib/rbac.ts` did not already declare, and CUSTOMER is unaffected:
34	 * a customer still reaches only their own ticket.
35	 */
36	/**
37	 * The session behind a ticket action, plus whether they are support staff.
38	 *
39	 * Named `require*` deliberately. `test/auth-lockouts.test.ts` enforces that every
40	 * export of a "use server" file — each of which is a network-callable endpoint
41	 * anyone can POST to — calls a recognised guard INSIDE the function, and it
42	 * recognises guards by the `require*`/`owned*`/`assert*`/`resolve*` convention.
43	 * This helper was `ticketActor`, which guarded correctly but did not LOOK like a
44	 * guard, so the tripwire reported three genuinely-safe endpoints as unguarded.
45	 *
46	 * The fix was the name, not the rule: widening the rule to accept arbitrary
47	 * helper names would let a future function that guards nothing pass the same
48	 * check. A guard should be recognisable as one.
49	 */
50	async function requireTicketActor(): Promise<{ id: string; isSupportStaff: boolean }> {
51	  const user = await requireUser();
52	  return { id: user.id, isSupportStaff: await hasAreaAccess(user, "supportTickets") };
53	}
54	
55	export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
56	  const user = await requireUser();
57	  const parsed = z
58	    .object({
59	      subject: z.string().min(3).max(150),
60	      body: z.string().min(5).max(10000),
61	      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
62	    })
63	    .safeParse({
64	      subject: formData.get("subject"),
65	      body: formData.get("body"),
66	      priority: formData.get("priority") ?? "NORMAL",
67	    });
68	  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };
69	
70	  const ticket = await createTicketCore({
71	    userId: user.id,
72	    subject: parsed.data.subject,
73	    body: parsed.data.body,
74	    priority: parsed.data.priority,
75	  });
76	  // Discord bridge (Phase 1 mirror): best-effort, never blocks ticket creation
77	  // or the redirect below — see lib/discord-bridge.ts's top-of-file comment.
78	  await mirrorNewTicketToDiscord(ticket.ticketId);
79	  redirect(`/dashboard/support/${ticket.ticketId}`);
80	}
81	
82	/** Sending a screenshot plus a few follow-up crops in one go is normal; sending
83	 *  fifty is not what the picker/paste flow below is for. */
84	const MAX_ATTACHMENTS_PER_REPLY = 6;
85	
86	export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
87	  const user = await requireTicketActor();
88	  const ticketId = String(formData.get("ticketId") ?? "");
89	  const body = String(formData.get("body") ?? "").trim();
90	
91	  // Ownership guard, kept directly in this "use server" boundary — every
92	  // export of this file is a public network endpoint (see this file's
93	  // top-of-file comment on the exact RBAC bug that made that non-obvious).
94	  // `writeTicketReply` (lib/reply-core.ts) re-checks this same thing before
95	  // writing, so this is deliberate defense-in-depth, not the only place it's
96	  // enforced — but a reviewer of THIS file should still see proof a customer
97	  // can only reply to their own ticket without having to trust an opaque
98	  // helper elsewhere.
99	  const ticketOwner = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
100	  if (!ticketOwner) return { error: "Ticket not found." };
101	  if (ticketOwner.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };
102	
103	  // Zero or more attachments (paste-multiple-images, or picking several files
104	  // at once). The same ownership guard above already covers who may attach —
105	  // a customer can only ever reach here for their own ticket, staff for any
106	  // ticket they can open. `formData.getAll` is how multiple entries under the
107	  // same `<input name="file" multiple>` arrive.
108	  const rawFiles = formData.getAll("file").filter((f): f is File => f instanceof File && f.size > 0);
109	  if (rawFiles.length > MAX_ATTACHMENTS_PER_REPLY) {
110	    return { error: `Attach at most ${MAX_ATTACHMENTS_PER_REPLY} files per message.` };
111	  }
112	  const attachments: { mime: string; name: string; size: number; data: Buffer }[] = [];
113	  for (const file of rawFiles) {
114	    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) {
115	      return { error: `"${file.name}" is larger than 10 MB.` };
116	    }
117	    const bytes = Buffer.from(await file.arrayBuffer());
118	    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
119	    if (!check.ok) return { error: `"${file.name}": ${check.error}` };
120	    attachments.push({ mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes });
121	  }
122	
123	  // The first attachment (if any) rides on the same message as the typed
124	  // body, exactly as a single-attachment reply always has. Any additional
125	  // ones are written directly here as their own attachment-only messages
126	  // from the same author, right behind it — `writeTicketReply` is the one
127	  // shared write path for tickets, live chat AND the Discord bridge, and it
128	  // fires one notification/email per call, so looping it per image would
129	  // spam staff with N notifications for what the customer experienced as a
130	  // single send. TicketThreadPanel re-clusters consecutive same-author sends
131	  // back into one visual bubble with an image grid.
132	  const result = await writeTicketReply({
133	    actorId: user.id,
134	    actorIsSupportStaff: user.isSupportStaff,
135	    ticketId,
136	    body,
137	    attachment: attachments[0],
138	  });
139	  if (result.error) return { error: result.error };
140	
141	  const extra = attachments.slice(1);
142	  if (extra.length) {
143	    await db.ticketMessage.createMany({
144	      data: extra.map((a) => ({
145	        ticketId,
146	        body: "",
147	        authorId: user.id,
148	        isStaff: Boolean(result.isStaff),
149	        attachmentData: new Uint8Array(a.data),
150	        attachmentMime: a.mime,
151	        attachmentName: a.name,
152	        attachmentSize: a.size,
153	      })),
154	    });
155	  }
156	
157	  // Discord bridge (Phase 1 mirror): best-effort. This reply was written from
158	  // the web dashboard, never from Discord (Discord-originated replies go
159	  // through app/api/webhooks/discord/route.ts, which calls writeTicketReply
160	  // directly and does NOT mirror — otherwise a Discord reply would echo right
161	  // back into the same Discord thread it came from).
162	  const attachNote = attachments.length
163	    ? attachments.length === 1
164	      ? `📎 ${attachments[0].name} (attachment — view in the dashboard)`
165	      : `📎 ${attachments.length} attachments (view in the dashboard)`
166	    : undefined;
167	  const mirrorBody = body || attachNote || "";
168	  await mirrorTicketReplyToDiscord(ticketId, mirrorBody, Boolean(result.isStaff));
169	
170	  revalidatePath(`/dashboard/support/${ticketId}`);
171	  revalidatePath(`/admin/support/${ticketId}`);
172	  return {};
173	}
174	
175	/**
176	 * "Is typing" signal — deliberately in-memory, never persisted. Every real
177	 * chat product treats typing indicators as throwaway state (Slack, Discord,
178	 * iMessage never write one to a database); a DB round trip for something
179	 * that expires in 4 seconds would be pure churn. This assumes a single Node
180	 * process, which is what this app runs as — if that ever changes, this map
181	 * would need to move to a shared store, but it does not need to yet.
182	 */
183	const typingPings = new Map<string, { staffAt: number; customerAt: number }>();
184	const TYPING_TTL_MS = 4000;
185	
186	function sweepTypingPings() {
187	  const cutoff = Date.now() - 5 * 60_000;
188	  for (const [id, v] of typingPings) {
189	    if (v.staffAt < cutoff && v.customerAt < cutoff) typingPings.delete(id);
190	  }
191	}
192	
193	/** Called (throttled, client-side) on every keystroke in a ticket's reply box. */
194	export async function pingTyping(ticketId: string): Promise<void> {
195	  const user = await requireTicketActor();
196	  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
197	  if (!ticket) return;
198	  if (ticket.userId !== user.id && !user.isSupportStaff) return;
199	  const isStaff = user.isSupportStaff && ticket.userId !== user.id;
200	  sweepTypingPings();
201	  const prev = typingPings.get(ticketId) ?? { staffAt: 0, customerAt: 0 };
202	  typingPings.set(ticketId, isStaff ? { ...prev, staffAt: Date.now() } : { ...prev, customerAt: Date.now() });
203	}
204	
205	/** Whether the OTHER party (relative to whoever's asking) is typing right now. */
206	export async function getTypingStatus(ticketId: string): Promise<{ typing: boolean }> {
207	  const user = await requireTicketActor();
208	  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
209	  if (!ticket) return { typing: false };
210	  if (ticket.userId !== user.id && !user.isSupportStaff) return { typing: false };
211	  const viewerIsStaff = user.isSupportStaff && ticket.userId !== user.id;
212	  const ping = typingPings.get(ticketId);
213	  if (!ping) return { typing: false };
214	  const at = viewerIsStaff ? ping.customerAt : ping.staffAt;
215	  return { typing: Date.now() - at < TYPING_TTL_MS };
216	}
217	
218	/**
219	 * A TypeScript parameter type is a compile-time comment on a network endpoint.
220	 *
221	 * Every export of this file is POST-able with any JSON the caller likes, so the
222	 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
223	 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
224	 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
225	 * the support queue's "needs a reply" view without anyone having replied. Values
226	 * outside the enum reached Prisma and threw, which surfaces as a server error
227	 * page rather than a message. Both are fixed by validating at the boundary.
228	 */
229	const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
230	const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;
231	
232	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
233	  const user = await requireTicketActor();
234	  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
235	    throw new Error("A ticket can only be reopened or closed from here.");
236	  }
237	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
238	  if (!ticket) throw new Error("Not found");
239	  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
240	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
241	  // Best-effort, never blocks the status change itself.
242	  void setDiscordThreadArchived("ticket", (ticket as any).discordThreadId, status === "CLOSED");
243	  revalidatePath(`/dashboard/support`);
244	  revalidatePath(`/dashboard/support/${ticketId}`);
245	  revalidatePath(`/admin/support`);
