273	export async function editTicketMessage(messageId: string, newBody: string): Promise<{ error?: string }> {
274	  const user = await requireUser();
275	  const body = newBody.trim();
276	  if (body.length < 2 || body.length > 10000) return { error: "Message must be between 2 and 10,000 characters." };
277	
278	  const message = await db.ticketMessage.findUnique({
279	    where: { id: messageId },
280	    include: { ticket: { select: { id: true, status: true } } },
281	  });
282	  if (!message) return { error: "Message not found." };
283	  if (message.authorId !== user.id) return { error: "You can only edit your own messages." };
284	  if (message.ticket.status === "CLOSED") return { error: "This ticket is closed." };
285	  if (Date.now() - message.createdAt.getTime() >= EDIT_WINDOW_MS) {
286	    return { error: "You can only edit a message within 5 minutes of sending it." };
287	  }
288	
289	  await db.ticketMessage.update({ where: { id: messageId }, data: { body, editedAt: new Date() } });
290	  revalidatePath(`/dashboard/support/${message.ticket.id}`);
291	  revalidatePath(`/admin/support/${message.ticket.id}`);
292	  return {};
293	}
