171	/**
172	 * Shared ticket-CREATION core, extracted from lib/actions-support.ts's
173	 * `createTicket` for the same reason writeTicketReply/writeChatReply above
174	 * were: a second caller (the Discord `/support` command,
175	 * app/api/webhooks/discord/route.ts) needs the exact same DB-write +
176	 * admin-notification behavior without the form action's FormData parsing or
177	 * its terminal `redirect()` (which only makes sense for a page navigation,
178	 * not an interaction response).
179	 *
180	 * Deliberately does NOT call mirrorNewTicketToDiscord itself — that would
181	 * import lib/discord-bridge.ts, which already imports FROM this file
182	 * (writeTicketReply/writeChatReply), creating a cycle. Every caller mirrors
183	 * the ticket itself right after calling this, exactly as `createTicket`
184	 * already did before this extraction.
185	 *
186	 * NO AUTHORIZATION CHECK HERE — same discipline as writeTicketReply above.
187	 * Every caller must resolve/validate `userId` itself first:
188	 *   - `createTicket` (lib/actions-support.ts) calls `requireUser()` first.
189	 *   - The Discord `/support` command resolves it via `User.discordUserId`
190	 *     (a real, signed Discord interaction) before calling in.
191	 */
192	export async function createTicketCore(args: {
193	  userId: string;
194	  subject: string;
195	  body: string;
196	  priority?: "LOW" | "NORMAL" | "HIGH" | "URGENT";
197	}): Promise<{ ticketId: string; subject: string }> {
198	  const ticket = await db.ticket.create({
199	    data: {
200	      subject: args.subject,
201	      priority: args.priority ?? "NORMAL",
202	      userId: args.userId,
203	      messages: { create: { body: args.body, authorId: args.userId, isStaff: false } },
204	    },
205	  });
206	  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
207	  await db.notification.createMany({
208	    data: admins.map((a) => ({
209	      userId: a.id,
210	      title: `New ticket: ${args.subject}`,
211	      href: `/admin/support/${ticket.id}`,
212	    })),
213	  });
214	  return { ticketId: ticket.id, subject: args.subject };
215	}
