2	
3	import { requireUser } from "@/lib/auth";
4	import { db } from "@/lib/db";
5	import { SupportView } from "@/components/nx/SupportView";
6	import { getHelpData } from "@/lib/help";
7	import { getHealth, overallStatus, uptimeSummary, listIncidents, HEALTH_COMPONENTS } from "@/lib/monitoring";
8	import { COMPONENT_LABELS } from "@/lib/status-copy";
9	
10	/* Support, on the concept's structure — Tickets / Live Chat / Help Center /
11	 * Service Status.
12	 *
13	 * The concept's stat strip also carries "99.8% Customer Satisfaction" — that
14	 * one has no backing data anywhere in this platform (no CSAT survey exists),
15	 * so it stays out. Its neighbour, "Avg response time", DOES now have a real
16	 * source: the gap between a ticket's own `createdAt` (the opening message)
17	 * and the first staff reply is a real, measured duration, not a marketing
18	 * SLA — so it is computed below from this customer's own ticket history
19	 * instead of being either fabricated or dropped. `null` ("not enough data
20	 * yet") when none of their tickets have a staff reply yet.
21	 *
22	 * What else IS measured: how many of your tickets are open, how many are
23	 * waiting on you, and how many closed recently (TicketStatus); the real Help
24	 * Center content (lib/help.ts, grouped published BlogPosts — the same data
25	 * /help runs on); and the real platform health/incident history
26	 * (lib/monitoring.ts — the same data the public /status page runs on).
27	 */
28	export default async function SupportPage({
29	  searchParams,
30	}: {
31	  searchParams: Promise<{ ticket?: string }>;
32	}) {
33	  const user = await requireUser();
34	  const { ticket: initialTicketId } = await searchParams;
35	  const monthAgo = new Date(Date.now() - 30 * 86_400_000);
36	
37	  const [tickets, closedRecently, firstStaffReplies, helpData, health, uptime, incidents] = await Promise.all([
38	    db.ticket.findMany({
39	      where: { userId: user.id },
40	      select: {
41	        id: true, subject: true, status: true, priority: true,
42	        createdAt: true, updatedAt: true,
43	      },
44	      orderBy: { updatedAt: "desc" },
45	      take: 40,
46	    }),
47	    db.ticket.count({
48	      where: { userId: user.id, status: "CLOSED", updatedAt: { gte: monthAgo } },
49	    }),
50	    db.ticketMessage.groupBy({
51	      by: ["ticketId"],
52	      where: { ticket: { userId: user.id }, isStaff: true },
53	      _min: { createdAt: true },
54	    }),
55	    getHelpData(),
56	    getHealth(),
57	    uptimeSummary(),
58	    listIncidents(),
59	  ]);
60	
61	  /* The latest message per ticket, for the list preview. This used to ride
62	     along as a nested `messages: { orderBy, take: 1 }` select on the ticket
63	     query above — but Prisma's default ("query") relation strategy has no
64	     SQL-level LIMIT per parent for a nested to-many `take`: it fetches EVERY
65	     TicketMessage row (full `body` text included) for all 40 tickets via a
66	     single `ticketId IN (...)` query, orders it, and only then discards all
67	     but the newest per ticket. For a long-running ticket thread that is a lot
68	     of wasted body bytes pulled over the wire and thrown away. Instead: get
69	     just the max(createdAt) per ticket (a cheap aggregate, no body), then
70	     fetch exactly those rows — at most one per ticket. */
71	  const ticketIds = tickets.map((t) => t.id);
72	  const lastMessageMeta = ticketIds.length
73	    ? await db.ticketMessage.groupBy({
74	        by: ["ticketId"],
75	        where: { ticketId: { in: ticketIds } },
76	        _max: { createdAt: true },
77	      })
78	    : [];
79	  const lastMessages = lastMessageMeta.length
80	    ? await db.ticketMessage.findMany({
81	        where: {
82	          OR: lastMessageMeta
83	            .filter((m) => m._max.createdAt)
84	            .map((m) => ({ ticketId: m.ticketId, createdAt: m._max.createdAt! })),
85	        },
86	        select: { ticketId: true, body: true, isStaff: true, createdAt: true },
87	      })
88	    : [];
89	  const lastMessageByTicket = new Map(lastMessages.map((m) => [m.ticketId, m]));
90	
91	  const rows = tickets.map((t) => {
92	    const last = lastMessageByTicket.get(t.id);
93	    return {
94	      id: t.id,
95	      subject: t.subject,
96	      status: t.status,
97	      priority: t.priority,
98	      updated: t.updatedAt.toISOString(),
99	      /* The last message, trimmed for the list. Staff or customer is marked so a
100	         reader can tell at a glance whose move it is. */
101	      preview: last?.body.replace(/\s+/g, " ").slice(0, 120) ?? "",
102	      lastFromStaff: last?.isStaff ?? false,
103	    };
104	  });
105	
106	  const firstReplyByTicket = new Map(firstStaffReplies.map((r) => [r.ticketId, r._min.createdAt]));
107	  const responseMinutes: number[] = [];
108	  for (const t of tickets) {
109	    const firstStaffAt = firstReplyByTicket.get(t.id);
110	    if (firstStaffAt) responseMinutes.push((firstStaffAt.getTime() - t.createdAt.getTime()) / 60000);
111	  }
112	  const avgResponseMin = responseMinutes.length > 0
113	    ? Math.round(responseMinutes.reduce((a, b) => a + b, 0) / responseMinutes.length)
114	    : null;
115	
116	  const help = helpData.sections.map((s) => ({
117	    name: s.category.name,
118	    slug: s.category.slug,
119	    emoji: s.category.emoji,
120	    blurb: s.category.blurb,
121	    count: s.posts.length,
122	  }));
123	
124	  /* Combine open + resolved into one recent-incidents list, newest first,
125	     capped small — this is a support tab, not the full status page. */
126	  const recentIncidents = [...incidents.open, ...incidents.resolved]
127	    .sort((a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime())
128	    .slice(0, 6);
129	
130	  return (
131	    <SupportView
132	      viewer={{ name: user.name ?? null, email: user.email ?? null }}
133	      viewerId={user.id}
134	      tickets={rows}
135	      open={rows.filter((t) => t.status !== "CLOSED").length}
136	      /* "Waiting for you" is ANSWERED — staff replied and the ball is in the
137	         customer's court. That is the state worth surfacing; it is the one they
138	         can act on. */
139	      waitingOnYou={rows.filter((t) => t.status === "ANSWERED").length}
140	      closedRecently={closedRecently}
141	      avgResponseMin={avgResponseMin}
142	      initialTicketId={initialTicketId ?? null}
143	      help={help}
144	      helpTotal={helpData.total}
145	      status={{
146	        overall: overallStatus(health),
147	        components: HEALTH_COMPONENTS.map((key) => ({
148	          key,
149	          label: COMPONENT_LABELS[key],
150	          status: health[key].status,
151	          uptimePct: uptime[key].pct,
152	        })),
153	        incidents: recentIncidents.map((inc) => ({
154	          id: inc.id,
155	          title: inc.title,
156	          body: inc.body,
157	          severity: inc.severity,
158	          startedAt: inc.startedAt,
159	          resolvedAt: inc.resolvedAt,
160	        })),
161	      }}
162	    />
163	  );
164	}
