3	import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState, type ClipboardEvent } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import { useVoiceDictation, VoiceMeter } from "@/components/customer/claude-code/voice";
6	
7	/**
8	 * Client-side `accept` string only — deliberately NOT imported from
9	 * lib/ticket-attachment.ts. That module (and lib/chat-attachment.ts beneath
10	 * it) uses `Buffer`, which has no business in a client bundle; the real
11	 * validation always happens server-side in `replyTicket`/`writeTicketReply`
12	 * regardless of what this attribute lets the picker show. Mirrors
13	 * components/ChatWidget.tsx's own local `ACCEPT_IMAGES` constant for the
14	 * same reason.
15	 */
16	const ACCEPT_ATTR =
17	  "image/png,image/jpeg,image/gif,image/webp,application/pdf,.pdf,text/plain,.txt,.log,application/zip,.zip";
18	
19	/** Mirrors the server's own cap (lib/actions-support.ts) so the picker stops
20	 *  a customer well before the "use server" boundary has to reject it. */
21	const MAX_FILES = 6;
22	
23	export type ReplyComposerHandle = { resetAttachment: () => void };
24	
25	type Staged = { id: string; file: File; previewUrl: string | null };
26	
27	function fmtSize(bytes: number): string {
28	  if (bytes < 1024) return `${bytes} B`;
29	  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
30	  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
31	}
32	
33	/**
34	 * Shared reply-box chrome for both the admin (`TicketControls.tsx`) and
35	 * customer (`TicketForms.tsx`) reply forms: the textarea, multi-file
36	 * attachment (picker + paste, with previews before sending), and voice
37	 * dictation. Renders a hidden `<input type="file" name="file" multiple>`
38	 * INSIDE the enclosing `<form>` so everything staged here rides along with a
39	 * normal form-action submit — no extra JS wiring needed at the call site
40	 * beyond mounting this component inside the form.
41	 *
42	 * Multiple files are kept as React state (`Staged[]`), the source of truth,
43	 * and mirrored onto the real input's `FileList` via a `DataTransfer` on every
44	 * change — the only way to hand a browser file input a list it didn't
45	 * originate (native pickers replace the whole list on each open; this lets
46	 * "Attach" be clicked more than once, or paste happen after a pick, and both
47	 * accumulate instead of clobbering each other).
48	 */
49	export const ReplyComposer = forwardRef<
50	  ReplyComposerHandle,
51	  {
52	    value: string;
53	    onChange: (value: string) => void;
54	    placeholder?: string;
55	    disabled?: boolean;
56	    className?: string;
57	    /** Fired (already throttled) on keystrokes — wire to a typing-ping action. */
58	    onTyping?: () => void;
59	  }
60	>(function ReplyComposer({ value, onChange, placeholder, disabled, className, onTyping }, ref) {
61	  const fileInputRef = useRef<HTMLInputElement>(null);
62	  const [staged, setStaged] = useState<Staged[]>([]);
63	  const [attachError, setAttachError] = useState<string | null>(null);
64	
65	  const dictation = useVoiceDictation(onChange);
66	  const lastTypingPing = useRef(0);
67	
68	  const syncInput = useCallback((list: Staged[]) => {
69	    const dt = new DataTransfer();
70	    for (const s of list) dt.items.add(s.file);
71	    if (fileInputRef.current) fileInputRef.current.files = dt.files;
72	  }, []);
73	
74	  const addFiles = useCallback(
75	    (incoming: File[]) => {
76	      if (!incoming.length) return;
77	      setStaged((prev) => {
78	        const room = MAX_FILES - prev.length;
79	        if (room <= 0) {
80	          setAttachError(`You can attach up to ${MAX_FILES} files per message.`);
81	          return prev;
82	        }
83	        const accepted = incoming.slice(0, room);
84	        if (incoming.length > accepted.length) {
85	          setAttachError(`Only the first ${MAX_FILES} files were kept — that's the limit per message.`);
86	        } else {
87	          setAttachError(null);
88	        }
89	        const next = [
90	          ...prev,
91	          ...accepted.map((file) => ({
92	            id: `${file.name}-${file.size}-${file.lastModified}-${Math.random().toString(36).slice(2, 7)}`,
93	            file,
94	            previewUrl: file.type.startsWith("image/") ? URL.createObjectURL(file) : null,
95	          })),
96	        ];
97	        syncInput(next);
98	        return next;
99	      });
100	    },
101	    [syncInput]
102	  );
103	
104	  function removeStaged(id: string) {
105	    setStaged((prev) => {
106	      const next = prev.filter((s) => s.id !== id);
107	      const dropped = prev.find((s) => s.id === id);
108	      if (dropped?.previewUrl) URL.revokeObjectURL(dropped.previewUrl);
109	      syncInput(next);
110	      return next;
111	    });
112	    setAttachError(null);
113	  }
114	
115	  function clearAttachment() {
116	    for (const s of staged) if (s.previewUrl) URL.revokeObjectURL(s.previewUrl);
117	    setStaged([]);
118	    setAttachError(null);
119	    if (fileInputRef.current) fileInputRef.current.value = "";
120	  }
121	
122	  useImperativeHandle(ref, () => ({ resetAttachment: clearAttachment }));
123	
124	  // Revoke any remaining object URLs on unmount.
125	  useEffect(() => () => { for (const s of staged) if (s.previewUrl) URL.revokeObjectURL(s.previewUrl); }, [staged]);
126	
127	  function handlePaste(e: ClipboardEvent<HTMLTextAreaElement>) {
128	    const images = Array.from(e.clipboardData?.items ?? [])
129	      .filter((i) => i.type.startsWith("image/"))
130	      .map((i) => i.getAsFile())
131	      .filter((f): f is File => f !== null);
132	    if (!images.length) return;
133	    e.preventDefault();
134	    addFiles(images.map((f, i) => new File([f], f.name || `pasted-image-${i + 1}.png`, { type: f.type || "image/png" })));
135	  }
136	
137	  function fireTyping() {
138	    if (!onTyping) return;
139	    const now = Date.now();
140	    if (now - lastTypingPing.current < 1500) return;
141	    lastTypingPing.current = now;
142	    onTyping();
143	  }
144	
145	  const listening = dictation.listening;
146	
147	  return (
148	    <div className={className}>
149	      <div className="relative">
150	        <textarea
151	          className={"input min-h-28 resize-y pr-3 transition-[box-shadow] " + (listening ? "ring-1 ring-[#5fd0ff]/50" : "")}
152	          name="body"
153	          placeholder={listening ? "Listening… speak your reply" : placeholder}
154	          disabled={disabled}
155	          value={value}
156	          onChange={(e) => { onChange(e.target.value); fireTyping(); }}
157	          onPaste={handlePaste}
158	        />
159	        {listening && (
160	          <div className="pointer-events-none absolute inset-0 rounded-[10px]"
161	               style={{ boxShadow: "0 0 0 1px rgba(95,208,255,.18), 0 0 22px rgba(95,208,255,.14) inset" }} aria-hidden />
162	        )}
163	      </div>
164	      <input
165	        ref={fileInputRef}
166	        type="file"
167	        name="file"
168	        multiple
169	        accept={ACCEPT_ATTR}
170	        className="hidden"
171	        disabled={disabled}
172	        onChange={(e) => { addFiles(Array.from(e.target.files ?? [])); e.target.value = ""; }}
173	      />
174	
175	      {staged.length > 0 && (
176	        <div className="mt-2.5 flex flex-wrap gap-2">
177	          {staged.map((s) => (
178	            <div key={s.id}
179	                 className="group relative h-16 w-16 flex-none overflow-hidden rounded-[10px] border border-rim-hi bg-well">
180	              {s.previewUrl ? (
181	                // eslint-disable-next-line @next/next/no-img-element -- local blob preview, never uploaded as-is.
182	                <img src={s.previewUrl} alt={s.file.name} className="h-full w-full object-cover" />
183	              ) : (
184	                <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-1 text-center">
185	                  <Icon name="file" size={16} className="text-tx-dim" />
186	                  <span className="w-full truncate text-[8.5px] leading-tight text-tx-faint">{s.file.name}</span>
187	                </div>
188	              )}
189	              <span className="absolute inset-x-0 bottom-0 bg-black/60 px-1 py-[1px] text-center text-[8px] text-white/80">
190	                {fmtSize(s.file.size)}
191	              </span>
192	              <button
193	                type="button"
194	                onClick={() => removeStaged(s.id)}
195	                aria-label={`Remove ${s.file.name}`}
196	                className="absolute right-0.5 top-0.5 grid h-4 w-4 place-items-center rounded-full bg-black/70 text-white opacity-0 transition-opacity group-hover:opacity-100"
197	              >
198	                <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
199	                  <path d="M18 6 6 18M6 6l12 12" />
200	                </svg>
201	              </button>
202	            </div>
203	          ))}
204	        </div>
205	      )}
206	      {attachError && <p className="mt-1.5 text-[11px] text-amber-300">{attachError}</p>}
207	      {dictation.error && <p className="mt-1.5 text-[11px] text-red-400">{dictation.error}</p>}
208	
209	      <div className="mt-2 flex flex-wrap items-center gap-2">
210	        <button
211	          type="button"
212	          disabled={disabled}
213	          onClick={() => fileInputRef.current?.click()}
214	          title="Attach files"
215	          className="inline-flex items-center gap-1.5 rounded-full border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] text-tx-dim transition hover:bg-[rgba(72,148,255,0.08)] hover:text-white"
216	        >
217	          <Icon name="paperclip" size={13} />
218	          Attach
219	        </button>
220	
221	        {dictation.supported && (
222	          <button
223	            type="button"
224	            disabled={disabled}
225	            onClick={() => void dictation.toggle(value)}
226	            title={listening ? "Stop dictation" : "Dictate with your microphone"}
227	            aria-pressed={listening}
228	            className={
229	              "relative inline-flex items-center gap-2 overflow-hidden rounded-full border px-2.5 py-1 text-[11.5px] transition " +
230	              (listening
231	                ? "border-[#5fd0ff]/40 bg-[rgba(95,208,255,0.08)] text-white"
232	                : "border-rim-hi bg-well text-tx-dim hover:bg-[rgba(72,148,255,0.08)] hover:text-white")
233	            }
234	          >
235	            <Icon name="mic" size={13} className={listening ? "nx-mic-live" : ""} />
236	            {listening ? (
237	              <>
238	                <VoiceMeter stream={dictation.stream} />
239	                <span>Listening…</span>
240	              </>
241	            ) : (
242	              <span>Dictate</span>
243	            )}
244	          </button>
245	        )}
246	
247	        {staged.length > 0 && (
248	          <span className="text-[10.5px] text-tx-faint">
249	            {staged.length} file{staged.length > 1 ? "s" : ""} attached
250	          </span>
251	        )}
252	      </div>
253	    </div>
254	  );
255	});
