568	 * lib/actions.ts for the same reason.
569	 *
570	 * Both were fixed by moving ONE function. Neither fix stopped it happening to
571	 * the next function, because nothing checked. These tests check — across every
572	 * "use server" module in lib/, on every export, every run.
573	 * ================================================================== */
574	
575	import { readdirSync } from "node:fs";
576	
577	/** Every lib/**\/*.ts whose FIRST statement is the "use server" directive. */
578	function useServerModules(): string[] {
579	  const out: string[] = [];
580	  const walk = (dir: string, prefix: string) => {
581	    for (const entry of readdirSync(new URL(dir, import.meta.url), { withFileTypes: true })) {
582	      if (entry.isDirectory()) walk(`${dir}${entry.name}/`, `${prefix}${entry.name}/`);
583	      else if (entry.name.endsWith(".ts")) {
584	        let src: string;
585	        try {
586	          src = readFileSync(new URL(`${dir}${entry.name}`, import.meta.url), "utf8");
587	        } catch {
588	          continue; // a sibling edit removed it mid-run
589	        }
590	        const first = src.split("\n").find((l) => l.trim() !== "");
591	        if (first && /^["']use server["']/.test(first.trim())) out.push(`${prefix}${entry.name}`);
592	      }
593	    }
594	  };
595	  walk("../lib/", "lib/");
596	  return out.sort();
597	}
598	
599	type Export = { name: string; line: number; isAsync: boolean; body: string };
600	
601	/** Top-level exported values in a module, with the body that follows each. */
602	function exportsOf(src: string): Export[] {
603	  const lines = src.split("\n");
604	  const found: Export[] = [];
605	  for (let i = 0; i < lines.length; i++) {
606	    const fn = /^export\s+(async\s+)?function\s+([A-Za-z0-9_]+)/.exec(lines[i]);
607	    const cn = /^export\s+const\s+([A-Za-z0-9_]+)\s*(?::[^=]*)?=\s*(async\s*)?/.exec(lines[i]);
608	    if (!fn && !cn) continue;
609	    const name = fn ? fn[2] : cn![1];
610	    const isAsync = fn ? Boolean(fn[1]) : Boolean(cn![2]);
611	    // The body ends at the first line that is NOTHING BUT a closing brace.
612	    // Not "starts with }": a multi-line return type closes as `}> {` and a
613	    // multi-line object parameter as `}): Promise<...> {`, both at column 0, and
614	    // that shape cut four genuinely-guarded actions off above their own guard
615	    // and reported them as unauthenticated. A tripwire that cries wolf gets muted.
616	    let body = "";
617	    for (let j = i; j < lines.length; j++) {
618	      body += lines[j] + "\n";
619	      if (j > i && /^[}\]]\s*;?\s*$/.test(lines[j])) break;
620	    }
621	    found.push({ name, line: i + 1, isAsync, body });
622	  }
623	  return found;
624	}
