/// A staff-initiated direct message thread to ONE customer — the lightweight
/// alternative to a formal support Ticket for the case a Ticket is wrong for:
/// staff wants to proactively reach a customer ("heads up, noticed X on your
/// server, wanted to flag it") with no customer action on record yet.
///
/// WHY A SEPARATE MODEL FROM Ticket, NOT A "staff-initiated" FLAG ON IT:
/// a Ticket's entire shape assumes the CUSTOMER opened it — `createTicketCore`
/// (lib/reply-core.ts) always attributes the opening message to the ticket's
/// own userId, `priority`/`status` (OPEN/ANSWERED/CUSTOMER_REPLY/CLOSED) model
/// a support QUEUE with an SLA clock, app/dashboard/support/page.tsx's
/// `avgResponseMin` reads `Ticket.createdAt` as "when the customer first
/// asked", and the Discord bridge mirrors every ticket into the support guild.
/// None of that means anything for a one-off staff note, and retrofitting a
/// flag onto Ticket would leave every one of those consumers silently wrong
/// unless it remembered to check it. A distinct model with its own (much
/// smaller) lifecycle keeps the two concepts, and their very different queue
/// semantics, apart — while still reusing Ticket's proven MESSAGE shape
/// (StaffDmMessage below is a deliberate copy of TicketMessage's columns:
/// read receipts, one attachment each) and UI conventions instead of
/// inventing a second message schema.
///
/// KEY DISTINCTION FROM A TICKET, ENFORCED BY THIS SHAPE (not just by
/// convention): nothing here requires the customer to have done anything
/// first — `createdById` is always a staff/admin user, `userId` is the
/// customer being messaged, and the first StaffDmMessage is authored by
/// staff. And unlike Ticket, a StaffDm is deliberately NEVER counted in or
/// listed alongside the customer's formal tickets anywhere (see
/// `user.tickets`/`_count.tickets` on app/admin/users/[id]/page.tsx and the
/// ticket query on app/dashboard/support/page.tsx) — it renders in its own
/// "Messages" tab on the customer Support page
/// (components/nx/SupportView.tsx) and its own "Direct messages" section on
/// the admin Customer 360 page, so a quick heads-up note never inflates a
/// customer's ticket history, changes their open-ticket count, or trips any
/// ticket-only automation.
///
/// NOT YET PUSHED to the live database — this worktree deliberately did not
/// run `prisma db push` (or regenerate the shared Prisma Client, which is
/// symlinked into the live /opt/nxeon node_modules) against the real, shared
/// Postgres instance. Run `npx prisma db push` (then `npx prisma generate`)
/// for real once this branch is reviewed and ready to promote.
model StaffDm {
  id      String @id @default(cuid())
  subject String
  /// OPEN | CLOSED only — no priority, no SLA. Staff-only to change
  /// (setStaffDmStatus in lib/actions-staff-dm.ts); a customer reply does
  /// NOT flip this the way it flips a Ticket back to CUSTOMER_REPLY, because
  /// there is no queue state here to hand back — the unread flags below
  /// already carry "does someone need to look at this."
  status String @default("OPEN")

  userId String
  user   User   @relation("StaffDmCustomer", fields: [userId], references: [id], onDelete: Cascade)

  createdById String
  createdBy   User   @relation("StaffDmCreatedBy", fields: [createdById], references: [id], onDelete: Cascade)

  messages StaffDmMessage[]

  /// Mirrors ChatConversation's unreadForAgent/unreadForUser — a cheap flag
  /// for the admin sidebar badge (app/admin/layout.tsx) and the customer nav
  /// badge (app/dashboard/layout.tsx) instead of scanning every message's
  /// readAt on every render. Flipped in lib/actions-staff-dm.ts on every send.
  unreadForStaff    Boolean @default(false)
  unreadForCustomer Boolean @default(true)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId, updatedAt])
  @@index([status, updatedAt])
}

/// A single message in a StaffDm thread. Deliberately the same shape as
/// TicketMessage (read receipt, one attachment) — see StaffDm's doc comment
/// for why the THREAD is a separate model while the MESSAGE columns are a
/// copy rather than something more clever (a shared polymorphic message
/// table would need a nullable ticketId/dmId pair on every existing
/// TicketMessage row and every query that reads one, for a feature that
/// touches neither).
model StaffDmMessage {
  id       String  @id @default(cuid())
  body     String
  isStaff  Boolean @default(true)
  dmId     String
  dm       StaffDm @relation(fields: [dmId], references: [id], onDelete: Cascade)
  authorId String
  author   User    @relation(fields: [authorId], references: [id], onDelete: Cascade)

  createdAt DateTime @default(now())

  /// Read receipt — staff -> customer visibility ONLY, identical convention
  /// to TicketMessage.readAt. Stamped by `getStaffDmThread`
  /// (lib/actions-staff-dm.ts) when the customer views the thread.
  readAt DateTime?

  /// One attachment per message, same validator and storage as
  /// TicketMessage (lib/ticket-attachment.ts) — served by
  /// app/api/dms/attachment/[id]/route.ts.
  attachmentData Bytes?
  attachmentMime String?
  attachmentName String?
  attachmentSize Int?

  @@index([dmId, createdAt])
}

