/**
 * Start a new DM to a customer — the STAFF-initiates-with-no-prior-customer-
 * action path a Ticket cannot offer. Called from the "Message customer"
 * control on the admin Customer 360 page (app/admin/users/[id]/page.tsx).
 *
 * Gated the same way a ticket reply is (`requireAnyGrant(["supportTickets"])`)
 * rather than `requireAdmin()` — SUPPORT staff can already reply to tickets
 * for any customer, and a quick heads-up DM is a lighter action than that,
 * not a heavier one.
 */
export async function startStaffDm(prev: any, formData: FormData): Promise<{ error?: string; dmId?: string }> {
  const staff = await requireAnyGrant(["supportTickets"]);

  const parsed = z
    .object({
      userId: z.string().min(1),
      subject: z.string().min(3).max(150),
      body: z.string().min(2).max(10000),
    })
    .safeParse({
      userId: formData.get("userId"),
      subject: formData.get("subject"),
      body: formData.get("body"),
    });
  if (!parsed.success) return { error: "A subject (3+ characters) and a message (2+ characters) are required." };

  const customer = await db.user.findUnique({ where: { id: parsed.data.userId }, select: { id: true, role: true } });
  if (!customer) return { error: "Customer not found." };
  if (customer.role !== "CUSTOMER") return { error: "You can only DM a customer account this way." };

  const dm = await db.staffDm.create({
    data: {
      subject: parsed.data.subject,
      userId: customer.id,
      createdById: staff.id,
      unreadForCustomer: true,
      unreadForStaff: false,
      messages: { create: { body: parsed.data.body, authorId: staff.id, isStaff: true } },
    },
  });

  await db.notification.create({
    data: {
      userId: customer.id,
      title: `New message from Nxeon staff: ${parsed.data.subject}`,
      href: `/dashboard/support?dm=${dm.id}`,
    },
  });

  revalidatePath(`/admin/users/${customer.id}`);
  revalidatePath("/admin/dms");
  return { dmId: dm.id };
}

/**
 * Reply to an existing DM thread — from either side. Mirrors
 * `replyTicket`/`writeTicketReply`'s ownership rule exactly: the thread's own
 * customer, or any support-staff member (any staff member may pick up any
 * customer's DM thread, same as tickets).
 */
export async function replyStaffDm(prev: any, formData: FormData): Promise<{ error?: string }> {
  const actor = await requireDmActor();
  const dmId = String(formData.get("dmId") ?? "");
  const body = String(formData.get("body") ?? "").trim();

  const dm = await db.staffDm.findUnique({ where: { id: dmId }, select: { id: true, userId: true, subject: true, status: true } });
  if (!dm) return { error: "Conversation not found." };
  if (dm.userId !== actor.id && !actor.isSupportStaff) return { error: "Forbidden." };
  if (dm.status === "CLOSED") return { error: "This conversation is closed." };

  const rawFiles = formData.getAll("file").filter((f): f is File => f instanceof File && f.size > 0);
  if (rawFiles.length > MAX_ATTACHMENTS_PER_REPLY) {
    return { error: `Attach at most ${MAX_ATTACHMENTS_PER_REPLY} files per message.` };
  }
  const attachments: { mime: string; name: string; size: number; data: Buffer }[] = [];
  for (const file of rawFiles) {
    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) return { error: `"${file.name}" is larger than 10 MB.` };
    const bytes = Buffer.from(await file.arrayBuffer());
    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
    if (!check.ok) return { error: `"${file.name}": ${check.error}` };
    attachments.push({ mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes });
  }
  if (!attachments.length && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };

  // A staff member replying to their OWN account (rare, but same override as
  // writeTicketReply) is not a "staff reply".
  const isStaff = actor.isSupportStaff && dm.userId !== actor.id;

  await db.$transaction([
    db.staffDmMessage.create({
      data: {
        dmId,
        body,
        authorId: actor.id,
        isStaff,
        ...(attachments[0]
          ? {
              attachmentData: new Uint8Array(attachments[0].data),
              attachmentMime: attachments[0].mime,
              attachmentName: attachments[0].name,
              attachmentSize: attachments[0].size,
            }
          : {}),
      },
    }),
    db.staffDm.update({
      where: { id: dmId },
      data: {
        updatedAt: new Date(),
        unreadForStaff: !isStaff,
        unreadForCustomer: isStaff,
      },
    }),
  ]);

  const extra = attachments.slice(1);
  if (extra.length) {
    await db.staffDmMessage.createMany({
      data: extra.map((a) => ({
        dmId,
        body: "",
        authorId: actor.id,
        isStaff,
        attachmentData: new Uint8Array(a.data),
        attachmentMime: a.mime,
        attachmentName: a.name,
        attachmentSize: a.size,
      })),
    });
  }

  if (isStaff) {
    await db.notification.create({
      data: {
        userId: dm.userId,
        title: `New message from Nxeon staff: ${dm.subject}`,
        href: `/dashboard/support?dm=${dmId}`,
      },
    });
  } else {
    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `Reply in DM: ${dm.subject}`,
        href: `/admin/dms/${dmId}`,
      })),
    });
  }

  revalidatePath(`/admin/dms/${dmId}`);
  revalidatePath("/admin/dms");
  revalidatePath("/dashboard/support");
  return {};
}

const DM_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;

/** Staff-only: open/close a DM thread. A customer never sets this — mirrors
 *  `setTicketStatus`'s shape, minus the Discord-archive side effect (a DM
 *  thread is never bridged to Discord). */
export async function setStaffDmStatus(dmId: string, status: "OPEN" | "CLOSED"): Promise<void> {
  await requireAnyGrant(["supportTickets"]);
  if (!DM_STATUS_CHOICES.includes(status)) throw new Error("A conversation can only be reopened or closed from here.");
  const dm = await db.staffDm.findUnique({ where: { id: dmId }, select: { id: true } });
  if (!dm) throw new Error("Not found");
  await db.staffDm.update({ where: { id: dmId }, data: { status } });
  revalidatePath(`/admin/dms/${dmId}`);
  revalidatePath("/admin/dms");
}

/** Stamp `readAt` on every unread staff message, and clear the customer's
 *  unread flag — called by `getStaffDmThread` when the owning customer opens
 *  the thread. Mirrors `markTicketMessagesRead`'s one-directional design. */
async function markStaffDmReadForCustomer(dmId: string, customerId: string): Promise<void> {
  await db.$transaction([
    db.staffDmMessage.updateMany({ where: { dmId, isStaff: true, readAt: null }, data: { readAt: new Date() } }),
    db.staffDm.update({ where: { id: dmId }, data: { unreadForCustomer: false } }),
  ]);
}

/** Staff-side equivalent — clears the staff unread flag when a staff member
 *  opens the admin thread view. No message-level receipt for this direction
 *  (customers never see staff read receipts on their own messages, per the
 *  same "read receipts from customers, but they don't get them from us" rule
 *  tickets use), just the inbox-badge flag. */
export async function markStaffDmReadForStaff(dmId: string): Promise<void> {
  await requireAnyGrant(["supportTickets"]);
  await db.staffDm.update({ where: { id: dmId }, data: { unreadForStaff: false } }).catch(() => {});
}

/**
 * One DM thread's full transcript, for the customer's in-page "Messages" tab
 * (components/nx/SupportView.tsx) — mirrors `getTicketThread` exactly. Only
 * the thread's own customer, or an admin, may fetch it.
 */
export async function getStaffDmThread(dmId: string): Promise<StaffDmThread | { error: string }> {
  const user = await requireUser();
  const dm = await db.staffDm.findUnique({
    where: { id: dmId },
    include: {
      messages: {
        orderBy: { createdAt: "asc" },
        include: { author: { select: { name: true } } },
      },
    },
  });
  if (!dm || (dm.userId !== user.id && user.role !== "ADMIN")) return { error: "not_found" };

  if (dm.userId === user.id) await markStaffDmReadForCustomer(dm.id, user.id);

  return {
    id: dm.id,
    subject: dm.subject,
    status: dm.status,
    createdAt: dm.createdAt.toISOString(),
    messages: dm.messages.map((m) => ({
      id: m.id,
      body: m.body,
      isStaff: m.isStaff,
      authorId: m.authorId,
      authorName: m.author.name ?? (m.isStaff ? "Nxeon staff" : "You"),
      createdAt: m.createdAt.toISOString(),
      attachmentMime: m.attachmentMime,
      attachmentName: m.attachmentName,
      attachmentSize: m.attachmentSize ?? 0,
    })),
  };
}

import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { isImageMime } from "@/lib/ticket-attachment";

export const runtime = "nodejs";

/**
 * GET /api/dms/attachment/[id] — stream a StaffDmMessage attachment ONLY to
 * an authorized viewer: any staff member (SUPPORT/ADMIN), or the customer the
 * DM thread belongs to. Copy of app/api/tickets/attachment/[id]/route.ts's
 * authorization model and response hardening, pointed at StaffDmMessage
 * instead of TicketMessage — see prisma/schema.prisma's StaffDm doc comment
 * for why these are separate models rather than one shared table.
 *
 * `id` is the StaffDmMessage id (a database id, never a filename).
 */
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });

  const message = await db.staffDmMessage.findUnique({
    where: { id },
    select: {
      attachmentData: true,
      attachmentMime: true,
      attachmentName: true,
      dm: { select: { userId: true } },
    },
  });
  if (!message || !message.attachmentData || !message.attachmentMime) {
    return new Response("Not found", { status: 404 });
  }

  const user = await currentUser();
  const authorized = !!user && (isStaff(user.role) || user.id === message.dm.userId);
  if (!authorized) return new Response("Forbidden", { status: 403 });

  const mime = message.attachmentMime;
  const isImage = isImageMime(mime);
  const data: Buffer = Buffer.isBuffer(message.attachmentData)
    ? message.attachmentData
    : Buffer.from(message.attachmentData as Uint8Array);

  const safeName = (message.attachmentName ?? "attachment").replace(/["\r\n]/g, "");
  const disposition = isImage ? `inline; filename="${safeName}"` : `attachment; filename="${safeName}"`;

  return new Response(new Uint8Array(data), {
    status: 200,
    headers: {
      "Content-Type": mime,
      "Content-Length": String(data.length),
      "Content-Disposition": disposition,
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
      "Cache-Control": "private, max-age=86400, no-transform",
    },
  });
}

import { fmtBytes } from "@/components/ui/primitives";
import { LightboxImage } from "@/components/ui/LightboxImage";

/**
 * Renders a StaffDmMessage's single attachment — a copy of
 * components/support/MessageAttachment.tsx pointed at
 * app/api/dms/attachment/[id]/route.ts instead of the ticket attachment
 * route. See prisma/schema.prisma's StaffDm doc comment for why DMs have
 * their own message model (and therefore their own attachment route) rather
 * than sharing TicketMessage's.
 */
export function DmMessageAttachment({
  messageId,
  mime,
  name,
  size,
}: {
  messageId: string;
  mime: string;
  name: string;
  size: number;
}) {
  const url = `/api/dms/attachment/${messageId}`;
  const isImage = mime.startsWith("image/");

  if (isImage) {
    return (
      <LightboxImage
        src={url}
        alt={name}
        wrapperClassName="mt-2"
        className="max-h-64 rounded-lg border border-white/10 object-contain"
      />
    );
  }

  return (
    <a
      href={url}
      download={name}
      className="mt-2 flex items-center gap-2 rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-slate-300 transition hover:bg-white/10"
    >
      <span aria-hidden>📄</span>
      <span className="truncate">{name}</span>
      <span className="ml-auto shrink-0 text-slate-500">{fmtBytes(size)}</span>
    </a>
  );
}

"use client";

import { useRef, useState, useTransition } from "react";
import { useActionState } from "react";
import { replyStaffDm, setStaffDmStatus } from "@/lib/actions-staff-dm";
import { ReplyComposer, type ReplyComposerHandle } from "@/components/support/ReplyComposer";
import { CannedReplyPicker } from "@/components/support/CannedReplyPicker";

/**
 * Reply box + status control for a StaffDm thread — copies of
 * components/admin/TicketControls.tsx's `ReplyForm`/`TicketStatusButton`
 * pointed at the DM actions instead of the ticket ones. Reuses the same
 * `ReplyComposer` (attachments, dictation) and `CannedReplyPicker` a ticket
 * reply uses, so staff get the same reply experience on a DM as on a ticket.
 */
export function DmReplyForm({ dmId }: { dmId: string }) {
  const formRef = useRef<HTMLFormElement>(null);
  const composerRef = useRef<ReplyComposerHandle>(null);
  const [body, setBody] = useState("");
  const [state, action, pending] = useActionState(
    async (prev: { error?: string }, fd: FormData) => {
      const res = await replyStaffDm(prev, fd);
      if (!res?.error) {
        formRef.current?.reset();
        composerRef.current?.resetAttachment();
        setBody("");
      }
      return res;
    },
    {} as { error?: string }
  );
  return (
    <form ref={formRef} action={action} className="space-y-3">
      <input type="hidden" name="dmId" value={dmId} />
      <ReplyComposer
        ref={composerRef}
        value={body}
        onChange={setBody}
        placeholder="Write a message as staff…"
        disabled={pending}
      />
      <div className="flex flex-wrap items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Sending…" : "Send message"}
        </button>
        <CannedReplyPicker
          disabled={pending}
          onInsert={(snippet) => setBody((prev) => (prev.trim() ? `${prev}\n\n${snippet}` : snippet))}
        />
        {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}

export function DmStatusButton({ dmId, closed }: { dmId: string; closed: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={closed ? "btn-secondary py-1.5" : "btn-danger py-1.5"}
      disabled={pending}
      onClick={() => start(() => setStaffDmStatus(dmId, closed ? "OPEN" : "CLOSED"))}
    >
      {closed ? "Reopen conversation" : "Close conversation"}
    </button>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";
import { DmReplyForm, DmStatusButton } from "@/components/admin/StaffDmControls";
import { DmMessageAttachment } from "@/components/support/DmMessageAttachment";
import { TicketBody } from "@/components/support/TicketBody";
import { ReadReceipt } from "@/components/support/ReadReceipt";
import { markStaffDmReadForStaff } from "@/lib/actions-staff-dm";

/**
 * A single staff DM thread — the admin equivalent of
 * components/admin/SupportTicketView.tsx, for StaffDm instead of Ticket. No
 * priority selector (a DM has none — see prisma/schema.prisma's StaffDm doc
 * comment) and no financials panel; otherwise the same message-bubble layout
 * so staff switching between a ticket and a DM see one visual language.
 */
export async function StaffDmThreadView({ id, currentUserId }: { id: string; currentUserId: string }) {
  const dm = await db.staffDm.findUnique({
    where: { id },
    include: {
      messages: {
        select: {
          id: true,
          body: true,
          isStaff: true,
          authorId: true,
          createdAt: true,
          readAt: true,
          attachmentMime: true,
          attachmentName: true,
          attachmentSize: true,
          author: { select: { name: true, role: true } },
        },
        orderBy: { createdAt: "asc" },
      },
      user: {
        select: {
          id: true,
          name: true,
          email: true,
          createdAt: true,
          _count: { select: { servers: true, tickets: true } },
        },
      },
      createdBy: { select: { name: true } },
    },
  });
  if (!dm) notFound();

  await markStaffDmReadForStaff(dm.id);

  const closed = dm.status === "CLOSED";

  return (
    <div className="flex flex-col gap-4 xl:h-[calc(100vh-8rem)]">
      <div className="shrink-0">
        <PageHeader
          title={dm.subject}
          sub={`Started by ${dm.createdBy.name} · ${dm.createdAt.toISOString().slice(0, 10)} · updated ${timeAgo(dm.updatedAt)}`}
        >
          <Badge tone="brand">direct message</Badge>
          <StatusDot status={dm.status} />
          <DmStatusButton dmId={dm.id} closed={closed} />
        </PageHeader>
      </div>

      <div className="grid flex-1 gap-4 xl:grid-cols-3 xl:overflow-hidden">
        <div className="flex flex-col gap-4 xl:col-span-2 xl:overflow-hidden">
          <div className="space-y-4 xl:flex-1 xl:overflow-y-auto xl:pr-1">
            {dm.messages.map((m) => (
              <div key={m.id} className={`flex ${m.isStaff ? "justify-end" : "justify-start"}`}>
                <div className="max-w-[85%]">
                  <div
                    className={`rounded-2xl px-4 py-3 text-sm ${
                      m.isStaff ? "border border-brand-500/30 bg-brand-500/10" : "glass border border-white/[0.08]"
                    }`}
                  >
                    <div className="mb-1.5 flex items-center gap-2 text-xs text-slate-400">
                      <span className="font-medium text-slate-300">{m.author.name}</span>
                      {m.isStaff && <Badge tone="brand">staff</Badge>}
                      <span>{timeAgo(m.createdAt)}</span>
                    </div>
                    {m.body && <TicketBody text={m.body} className="whitespace-pre-wrap leading-relaxed" />}
                    {m.attachmentMime && m.attachmentName && (
                      <DmMessageAttachment
                        messageId={m.id}
                        mime={m.attachmentMime}
                        name={m.attachmentName}
                        size={m.attachmentSize ?? 0}
                      />
                    )}
                  </div>
                  {m.isStaff && (
                    <div className="mt-1 flex justify-end">
                      <ReadReceipt readAt={m.readAt} />
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>

          <div className="card shrink-0">
            <h2 className="mb-3 font-semibold">Reply as staff</h2>
            {closed ? (
              <p className="text-sm text-slate-500">
                This conversation is closed — reopen it above to continue.
              </p>
            ) : (
              <DmReplyForm dmId={dm.id} />
            )}
          </div>
        </div>

        <div className="space-y-4 xl:overflow-y-auto">
          <div className="card">
            <h2 className="mb-4 font-semibold">Customer</h2>
            <dl className="space-y-2.5 text-sm">
              <div className="flex justify-between gap-3">
                <dt className="text-slate-500">Name</dt>
                <dd className="text-right">
                  <Link href={`/admin/users/${dm.user.id}`} className="font-medium hover:text-brand-300">
                    {dm.user.name}
                  </Link>
                </dd>
              </div>
              <div className="flex justify-between gap-3">
                <dt className="text-slate-500">Email</dt>
                <dd className="truncate text-right">
                  <Link href={`/admin/users/${dm.user.id}`} className="hover:text-brand-300">
                    {dm.user.email}
                  </Link>
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Servers</dt>
                <dd>{dm.user._count.servers}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Tickets total</dt>
                <dd>{dm.user._count.tickets}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Joined</dt>
                <dd>{dm.user.createdAt.toISOString().slice(0, 10)}</dd>
              </div>
            </dl>
            <Link href={`/admin/users/${dm.user.id}`} className="btn-secondary mt-4 w-full text-center">
              Open customer 360 →
            </Link>
          </div>

          <div className="card">
            <h2 className="mb-2 font-semibold">What this is</h2>
            <p className="text-xs leading-relaxed text-slate-500">
              A direct message, not a support ticket — it doesn&apos;t count toward this
              customer&apos;s ticket history and carries no priority or SLA. Use it for a quick
              heads-up or follow-up; open a real ticket instead for anything that needs formal
              tracking.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

