import { requireAreaOrGrant } from "@/lib/staff-grants";
import { StaffDmThreadView } from "@/components/admin/StaffDmThreadView";

export const dynamic = "force-dynamic";

export default async function AdminDmThread({ params }: { params: Promise<{ id: string }> }) {
  const staff = await requireAreaOrGrant("supportTickets");
  const { id } = await params;
  return <StaffDmThreadView id={id} currentUserId={staff.id} />;
}

import Link from "next/link";
import { db } from "@/lib/db";
import { PageHeader, StatCard, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";

/**
 * The staff DM inbox — a copy of components/admin/SupportDeskView.tsx's
 * queue shape, pointed at StaffDm instead of Ticket. No priority column (a
 * DM has none) and sorted purely by recency with "needs a reply" (
 * `unreadForStaff`) surfaced first, since there's no urgency triage here —
 * see prisma/schema.prisma's StaffDm doc comment for why.
 *
 * This is the "find any thread" view; the more common path to a single
 * thread is starting or continuing it from a customer's Customer 360 page
 * (app/admin/users/[id]/page.tsx's "Message customer" control and "Direct
 * messages" section).
 */
export async function DmInboxView() {
  const [dms, unreadForStaff, openCount] = await Promise.all([
    db.staffDm.findMany({
      include: {
        user: { select: { id: true, email: true, name: true } },
        _count: { select: { messages: true } },
      },
      orderBy: { updatedAt: "desc" },
      take: 200,
    }),
    db.staffDm.count({ where: { unreadForStaff: true } }),
    db.staffDm.count({ where: { status: "OPEN" } }),
  ]);

  const sorted = [...dms].sort((a, b) => {
    const aClosed = a.status === "CLOSED" ? 1 : 0;
    const bClosed = b.status === "CLOSED" ? 1 : 0;
    if (aClosed !== bClosed) return aClosed - bClosed;
    if (a.unreadForStaff !== b.unreadForStaff) return a.unreadForStaff ? -1 : 1;
    return b.updatedAt.getTime() - a.updatedAt.getTime();
  });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Direct messages"
        sub="Lightweight, staff-initiated messages to individual customers — separate from the ticket queue."
      />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-3">
        <StatCard label="Open" value={String(openCount)} />
        <StatCard label="Awaiting staff reply" value={String(unreadForStaff)} deltaGood={unreadForStaff === 0} />
        <StatCard label="Total threads" value={String(dms.length)} />
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Subject</th>
              <th>Customer</th>
              <th>Status</th>
              <th>Messages</th>
              <th className="text-right">Updated</th>
            </tr>
          </thead>
          <tbody>
            {sorted.length === 0 && (
              <tr>
                <td colSpan={5} className="py-10 text-center text-slate-500">
                  No direct messages yet — start one from a customer&apos;s profile.
                </td>
              </tr>
            )}
            {sorted.map((dm) => (
              <tr key={dm.id} className={dm.status === "CLOSED" ? "opacity-60" : undefined}>
                <td>
                  <Link href={`/admin/dms/${dm.id}`} className="font-medium hover:text-brand-300">
                    {dm.subject}
                  </Link>
                  {dm.unreadForStaff && (
                    <span className="ml-2">
                      <Badge tone="amber">reply waiting</Badge>
                    </span>
                  )}
                </td>
                <td>
                  <Link href={`/admin/users/${dm.user.id}`} className="text-slate-300 hover:text-brand-300">
                    {dm.user.email}
                  </Link>
                </td>
                <td>
                  <StatusDot status={dm.status} />
                </td>
                <td>{dm._count.messages}</td>
                <td className="text-right text-xs text-slate-400">{timeAgo(dm.updatedAt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

