2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { dmDb } from "./staff-dm-db";
7	import { requireUser } from "./auth";
8	import { hasAreaAccess, requireAnyGrant } from "./staff-grants";
9	import { validateTicketAttachmentBytes, MAX_TICKET_ATTACHMENT_BYTES } from "./ticket-attachment";
10	
11	/**
12	 * Server actions for staff-initiated direct messages (StaffDm/StaffDmMessage
13	 * — see prisma/schema.prisma for why this is a separate model from Ticket).
14	 *
15	 * Every export here is a "use server" network endpoint (see
16	 * lib/actions-support.ts's top-of-file comment and test/auth-lockouts.test.ts,
17	 * which enforces this across every such module) — each guards itself
18	 * directly, the same discipline as the ticket actions this mirrors.
19	 */
20	
21	/** Same cap as a ticket reply (components/support/ReplyComposer.tsx). */
22	const MAX_ATTACHMENTS_PER_REPLY = 6;
23	
24	/** The session behind a DM action, plus whether they are support staff. */
25	async function requireDmActor(): Promise<{ id: string; isSupportStaff: boolean }> {
26	  const user = await requireUser();
27	  return { id: user.id, isSupportStaff: await hasAreaAccess(user, "supportTickets") };
28	}
29	
30	export type StaffDmSummary = {
31	  id: string;
32	  subject: string;
33	  status: string;
34	  updatedAt: string;
35	  unreadForCustomer: boolean;
36	  preview: string;
37	  lastFromStaff: boolean;
38	};
39	
40	export type StaffDmThreadMessage = {
41	  id: string;
42	  body: string;
43	  isStaff: boolean;
44	  authorId: string;
45	  authorName: string;
46	  createdAt: string;
47	  attachmentMime: string | null;
48	  attachmentName: string | null;
49	  attachmentSize: number;
50	};
51	
52	export type StaffDmThread = {
53	  id: string;
54	  subject: string;
55	  status: string;
56	  createdAt: string;
57	  messages: StaffDmThreadMessage[];
58	};
59	
60	/**
61	 * Start a new DM to a customer — the STAFF-initiates-with-no-prior-customer-
62	 * action path a Ticket cannot offer. Called from the "Message customer"
63	 * control on the admin Customer 360 page (app/admin/users/[id]/page.tsx).
64	 *
65	 * Gated the same way a ticket reply is (`requireAnyGrant(["supportTickets"])`)
66	 * rather than `requireAdmin()` — SUPPORT staff can already reply to tickets
67	 * for any customer, and a quick heads-up DM is a lighter action than that,
68	 * not a heavier one.
69	 */
70	export async function startStaffDm(prev: any, formData: FormData): Promise<{ error?: string; dmId?: string }> {
71	  const staff = await requireAnyGrant(["supportTickets"]);
72	
73	  const parsed = z
74	    .object({
75	      userId: z.string().min(1),
76	      subject: z.string().min(3).max(150),
77	      body: z.string().min(2).max(10000),
78	    })
79	    .safeParse({
80	      userId: formData.get("userId"),
81	      subject: formData.get("subject"),
82	      body: formData.get("body"),
83	    });
84	  if (!parsed.success) return { error: "A subject (3+ characters) and a message (2+ characters) are required." };
85	
86	  const customer = await db.user.findUnique({ where: { id: parsed.data.userId }, select: { id: true, role: true } });
87	  if (!customer) return { error: "Customer not found." };
88	  if (customer.role !== "CUSTOMER") return { error: "You can only DM a customer account this way." };
89	
90	  const dm = await dmDb.staffDm.create({
91	    data: {
92	      subject: parsed.data.subject,
93	      userId: customer.id,
94	      createdById: staff.id,
95	      unreadForCustomer: true,
96	      unreadForStaff: false,
97	      messages: { create: { body: parsed.data.body, authorId: staff.id, isStaff: true } },
98	    },
99	  });
100	
101	  await db.notification.create({
102	    data: {
103	      userId: customer.id,
104	      title: `New message from Nxeon staff: ${parsed.data.subject}`,
105	      href: `/dashboard/support?dm=${dm.id}`,
106	    },
107	  });
108	
109	  revalidatePath(`/admin/users/${customer.id}`);
110	  revalidatePath("/admin/dms");
111	  return { dmId: dm.id };
112	}
113	
114	/**
115	 * Reply to an existing DM thread — from either side. Mirrors
116	 * `replyTicket`/`writeTicketReply`'s ownership rule exactly: the thread's own
117	 * customer, or any support-staff member (any staff member may pick up any
118	 * customer's DM thread, same as tickets).
119	 */
120	export async function replyStaffDm(prev: any, formData: FormData): Promise<{ error?: string }> {
121	  const actor = await requireDmActor();
122	  const dmId = String(formData.get("dmId") ?? "");
123	  const body = String(formData.get("body") ?? "").trim();
124	
125	  const dm = await dmDb.staffDm.findUnique({ where: { id: dmId }, select: { id: true, userId: true, subject: true, status: true } });
126	  if (!dm) return { error: "Conversation not found." };
127	  if (dm.userId !== actor.id && !actor.isSupportStaff) return { error: "Forbidden." };
128	  if (dm.status === "CLOSED") return { error: "This conversation is closed." };
129	
130	  const rawFiles = formData.getAll("file").filter((f): f is File => f instanceof File && f.size > 0);
131	  if (rawFiles.length > MAX_ATTACHMENTS_PER_REPLY) {
132	    return { error: `Attach at most ${MAX_ATTACHMENTS_PER_REPLY} files per message.` };
133	  }
134	  const attachments: { mime: string; name: string; size: number; data: Buffer }[] = [];
135	  for (const file of rawFiles) {
136	    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) return { error: `"${file.name}" is larger than 10 MB.` };
137	    const bytes = Buffer.from(await file.arrayBuffer());
138	    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
139	    if (!check.ok) return { error: `"${file.name}": ${check.error}` };
140	    attachments.push({ mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes });
141	  }
142	  if (!attachments.length && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };
143	
144	  // A staff member replying to their OWN account (rare, but same override as
145	  // writeTicketReply) is not a "staff reply".
146	  const isStaff = actor.isSupportStaff && dm.userId !== actor.id;
147	
148	  await db.$transaction([
149	    dmDb.staffDmMessage.create({
150	      data: {
151	        dmId,
152	        body,
153	        authorId: actor.id,
154	        isStaff,
155	        ...(attachments[0]
156	          ? {
157	              attachmentData: new Uint8Array(attachments[0].data),
158	              attachmentMime: attachments[0].mime,
159	              attachmentName: attachments[0].name,
160	              attachmentSize: attachments[0].size,
161	            }
162	          : {}),
163	      },
164	    }),
165	    dmDb.staffDm.update({
166	      where: { id: dmId },
167	      data: {
168	        updatedAt: new Date(),
169	        unreadForStaff: !isStaff,
170	        unreadForCustomer: isStaff,
171	      },
172	    }),
173	  ]);
174	
175	  const extra = attachments.slice(1);
176	  if (extra.length) {
177	    await dmDb.staffDmMessage.createMany({
178	      data: extra.map((a) => ({
179	        dmId,
180	        body: "",
181	        authorId: actor.id,
182	        isStaff,
183	        attachmentData: new Uint8Array(a.data),
184	        attachmentMime: a.mime,
185	        attachmentName: a.name,
186	        attachmentSize: a.size,
187	      })),
188	    });
189	  }
190	
191	  if (isStaff) {
192	    await db.notification.create({
193	      data: {
194	        userId: dm.userId,
195	        title: `New message from Nxeon staff: ${dm.subject}`,
196	        href: `/dashboard/support?dm=${dmId}`,
197	      },
198	    });
199	  } else {
200	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
201	    await db.notification.createMany({
202	      data: admins.map((a) => ({
203	        userId: a.id,
204	        title: `Reply in DM: ${dm.subject}`,
205	        href: `/admin/dms/${dmId}`,
206	      })),
207	    });
208	  }
209	
210	  revalidatePath(`/admin/dms/${dmId}`);
211	  revalidatePath("/admin/dms");
212	  revalidatePath("/dashboard/support");
213	  return {};
214	}
