"use client";

import { useEffect, useRef, useState } from "react";
import { useActionState } from "react";
import { useRouter } from "next/navigation";
import { startStaffDm } from "@/lib/actions-staff-dm";

/**
 * "Message customer" — the entry point for a staff-initiated direct message,
 * from the Customer 360 page (app/admin/users/[id]/page.tsx). Unlike the
 * ticket/chat controls this sits beside, it needs no existing thread to
 * attach to: a staff member can open this on ANY customer's profile with no
 * prior ticket or chat message on record, which is the entire point of a DM
 * versus a ticket (see prisma/schema.prisma's StaffDm doc comment).
 *
 * A small inline popover rather than a full-page form — this is meant to be
 * a quick "heads up about X" note, not a formal compose screen.
 */
export function MessageCustomerButton({ userId }: { userId: string }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const [state, action, pending] = useActionState(
    async (prev: { error?: string; dmId?: string }, fd: FormData) => startStaffDm(prev, fd),
    {} as { error?: string; dmId?: string },
  );

  useEffect(() => {
    if (state?.dmId) router.push(`/admin/dms/${state.dmId}`);
  }, [state?.dmId, router]);

  useEffect(() => {
    if (!open) return;
    function onDocClick(e: MouseEvent) {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [open]);

  return (
    <div className="relative" ref={rootRef}>
      <button type="button" className="btn-secondary" onClick={() => setOpen((v) => !v)}>
        Message customer
      </button>
      {open && (
