"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import { createTicket, replyTicket, setTicketStatus, pingTyping } from "@/lib/actions-support";
import { ReplyComposer, type ReplyComposerHandle } from "@/components/support/ReplyComposer";

export function NewTicketForm({
  open: openProp, onOpenChange,
}: { open?: boolean; onOpenChange?: (open: boolean) => void } = {}) {
  // Controlled if a parent passes `open`/`onOpenChange` (the Support page's
  // header CTA opens this same form from outside it), otherwise manages its
  // own state exactly as before — every other/future plain `<NewTicketForm/>`
  // call site is unaffected.
  const [openState, setOpenState] = useState(false);
  const open = openProp ?? openState;
  const setOpen = onOpenChange ?? setOpenState;
  const [state, action, pending] = useActionState(createTicket, {});
  // CONTROLLED, deliberately. React 19 resets uncontrolled inputs on every
  // `<form action={fn}>` submit, so a rejected ticket came back with the subject
  // and the body — up to 10,000 characters — blank. The person retyping it is by
  // definition someone who already has a problem and has just been told "no".
  //
  // This is the same reset that permanently locked customers out of 2FA login
  // (see components/AuthForms.tsx). There the cost was the account; here it is
  // the customer's own words, which they will not write twice.
  const [subject, setSubject] = useState("");
  const [priority, setPriority] = useState("NORMAL");
  const [body, setBody] = useState("");

  // Esc closes the modal, same as clicking the backdrop or the X — standard
  // dialog behaviour, and cheap to add now that this is an actual overlay.
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  return (
    <>
      {/* Controlled usage supplies its own trigger button elsewhere (the
          Support page's "+ New Support Ticket" CTAs) — rendering one here too
          would be redundant. Uncontrolled usage still needs its own. */}
      {openProp === undefined && (
        <div className="flex justify-end">
          <button className="btn-primary" onClick={() => setOpen(true)}>+ New ticket</button>
        </div>
      )}
      {/* A centered popup instead of expanding in place — the sidebar column
          this used to open inline in (the Support page's "Start a
          conversation" panel) was only ~300px wide, cramming subject +
          priority into a squeezed two-up row. A modal gets real width for
          the same three fields. */}
      {open && (
        <div
          className="fixed inset-0 z-[80] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm motion-safe:animate-fade-up"
          onClick={(e) => { if (e.target === e.currentTarget) setOpen(false); }}
        >
          {/* The scroll lives on an INNER wrapper, not this card itself —
              `.card-glass`'s corner-glow pseudo-elements bleed outside their
              own box on purpose (see globals.css), and putting `overflow-y`
              on the same element that draws them clips that glow against the
              scrollport, which is what was reading as a stray line down the
              edge. This element only ever needs `overflow: hidden` (its own
              rounded corners), which `.card-glass` already sets. */}
          <div className="card card-glass relative flex w-full max-w-[560px] max-h-[90vh] flex-col p-0"
               style={{ "--tone": "#a05cf0" } as React.CSSProperties}>
            <div className="flex flex-none items-center justify-between px-6 pb-4 pt-6">
              <h2 className="text-[18px] font-extrabold text-white">New support ticket</h2>
              <button aria-label="Close" onClick={() => setOpen(false)}
                      className="rounded-lg p-1.5 text-tx-faint hover:bg-white/10 hover:text-white">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form action={action} className="space-y-4 overflow-y-auto px-6 pb-6">
              {state?.error && (
                <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
                  {state.error}
                </div>
              )}
              <div className="grid gap-4 sm:grid-cols-[1fr_180px]">
                <div>
                  <label className="label">Subject</label>
                  <input
                    className="input"
                    name="subject"
                    required
                    minLength={3}
                    maxLength={150}
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                    placeholder="Briefly, what's going on?"
                  />
                </div>
                <div>
                  <label className="label">Priority</label>
                  <select className="input" name="priority" value={priority} onChange={(e) => setPriority(e.target.value)}>
                    <option value="LOW">Low</option>
                    <option value="NORMAL">Normal</option>
                    <option value="HIGH">High</option>
                    <option value="URGENT">Urgent</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="label">Message</label>
                <textarea
                  className="input min-h-32 resize-y"
                  name="body"
                  required
                  minLength={5}
                  maxLength={10000}
                  value={body}
                  onChange={(e) => setBody(e.target.value)}
                  placeholder="Include the server hostname and any error messages — the more detail, the faster we can help."
                />
              </div>
              <div className="flex justify-end gap-2">
                <button type="button" className="btn-secondary px-6" onClick={() => setOpen(false)}>
                  Cancel
                </button>
                <button className="btn-primary px-6" disabled={pending}>
                  {pending ? "Opening…" : "Open ticket"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
}

export function ReplyForm({ ticketId, onSent }: { ticketId: string; onSent?: () => void }) {
  const [state, action, pending] = useActionState(replyTicket, {});
  const [body, setBody] = useState("");
  const composerRef = useRef<ReplyComposerHandle>(null);
  // A reply has two outcomes and they want OPPOSITE things from the field, which
  // is why simply making it controlled is not enough:
  //   - rejected  → keep every character; React 19 would otherwise blank up to
  //                 10,000 of them on the form-action submit, and the customer
  //                 will not retype them.
  //   - accepted  → clear it, or the sent reply sits there looking unsent and
  //                 gets sent twice.
  // So the field is controlled and cleared only on a submit that came back
  // without an error, watching the pending edge rather than the state shape
  // (the action returns `{}` for success, which is indistinguishable from its
  // initial value).
  const wasPending = useRef(false);
  useEffect(() => {
    if (wasPending.current && !pending && !state?.error) {
      setBody("");
      composerRef.current?.resetAttachment();
      // Optional — the Support page's inline thread view (no page navigation,
      // so no revalidatePath re-render) uses this to refetch the thread right
      // away instead of waiting for its own poll tick.
      onSent?.();
    }
    wasPending.current = pending;
  }, [pending, state, onSent]);
  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="ticketId" value={ticketId} />
      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
      <ReplyComposer
        ref={composerRef}
        value={body}
        onChange={setBody}
        placeholder="Write a reply…"
        disabled={pending}
        onTyping={() => void pingTyping(ticketId)}
      />
      <div className="flex justify-end">
        <button className="btn-primary px-6" disabled={pending}>
          {pending ? "Sending…" : "Send reply"}
        </button>
      </div>
    </form>
  );
}

export function TicketStatusButton({ ticketId, status, onChanged }: { ticketId: string; status: string; onChanged?: () => void }) {
  const [pending, start] = useTransition();
  const closed = status === "CLOSED";
  return (
    <button
      className={closed ? "btn-secondary" : "btn-danger"}
      disabled={pending}
      onClick={() => start(async () => {
        await setTicketStatus(ticketId, closed ? "OPEN" : "CLOSED");
        onChanged?.();
      })}
    >
      {pending ? "…" : closed ? "Reopen ticket" : "Close ticket"}
    </button>
  );
}

