"use client";

import { useActionState, useEffect, useRef, useState } from "react";
import { replyStaffDm } from "@/lib/actions-staff-dm";
import { ReplyComposer, type ReplyComposerHandle } from "@/components/support/ReplyComposer";

/**
 * Customer-side reply box for a StaffDm thread — a copy of
 * components/customer/TicketForms.tsx's `ReplyForm`, pointed at
 * `replyStaffDm` instead of `replyTicket`. Same controlled-field discipline:
 * a rejected send keeps every character (React 19 blanks uncontrolled
 * fields on a form action, which is the exact bug class
 * test/auth-lockouts.test.ts's H6 tests guard against for the auth forms),
 * a successful one clears it.
 */
export function DmReplyForm({ dmId, onSent }: { dmId: string; onSent?: () => void }) {
  const [state, action, pending] = useActionState(replyStaffDm, {});
  const [body, setBody] = useState("");
  const composerRef = useRef<ReplyComposerHandle>(null);
  const wasPending = useRef(false);

  useEffect(() => {
    if (wasPending.current && !pending && !state?.error) {
      setBody("");
      composerRef.current?.resetAttachment();
      onSent?.();
    }
    wasPending.current = pending;
  }, [pending, state, onSent]);

  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="dmId" value={dmId} />
      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
      <ReplyComposer ref={composerRef} value={body} onChange={setBody} placeholder="Write a reply…" disabled={pending} />
      <div className="flex justify-end">
        <button className="btn-primary px-6" disabled={pending}>
          {pending ? "Sending…" : "Send reply"}
        </button>
      </div>
    </form>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import { DmReplyForm } from "@/components/customer/DmReplyForm";
import { getStaffDmThread, type StaffDmThread } from "@/lib/actions-staff-dm";

export type DmSummary = {
  id: string;
  subject: string;
  status: string;
  updatedAt: string;
  unreadForCustomer: boolean;
  preview: string;
};

function ago(iso: string): string {
  const m = Math.max(1, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
  if (m < 60) return `${m}m ago`;
  const h = Math.round(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.round(h / 24)}d ago`;
}

/**
 * A small status pill — the same visual weight as SupportView's ticket
 * StatusTag, but not imported from there (that component isn't exported):
 * a DM only ever has two states (OPEN/CLOSED), so a tiny local version is
 * simpler than exporting and generalizing the ticket one for a third caller.
 */
function DmStatusPill({ status }: { status: string }) {
  const open = status !== "CLOSED";
  return (
    <span className={"nx-tag " + (open ? "nx-tag-cyan nx-tag-pulse" : "nx-tag-mint")}>
      <span className="nx-tag-dot" aria-hidden />
      {open ? "Open" : "Closed"}
    </span>
  );
}

/**
 * The customer-facing "Messages" tab on the Support page
 * (components/nx/SupportView.tsx) — staff-initiated direct messages, kept
 * deliberately separate from the "My Tickets" tab right next to it. See
 * prisma/schema.prisma's StaffDm doc comment for why this is not just
 * another row in the tickets list: a DM never counts toward this customer's
 * ticket history, has no priority/SLA, and can only ever be started by
 * staff — this tab is purely a "here's what Nxeon staff have sent you"
 * inbox, plus the ability to reply.
 */
export function DmMessagesPanel({
  dms,
  initialDmId,
}: {
  dms: DmSummary[];
  initialDmId: string | null;
}) {
  const router = useRouter();
  const [openDm, setOpenDm] = useState<StaffDmThread | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const openedInitial = useRef(false);

  async function openDmById(id: string) {
    setErr(null);
    setLoading(true);
    const res = await getStaffDmThread(id);
    setLoading(false);
    if ("error" in res) {
      setErr("That conversation couldn't be found.");
      return;
    }
    setOpenDm(res);
    router.replace(`/dashboard/support?dm=${id}`, { scroll: false });
  }

  async function refreshOpenDm(id: string) {
    const res = await getStaffDmThread(id);
    if (!("error" in res)) setOpenDm(res);
  }

  function backToList() {
    setOpenDm(null);
    setErr(null);
    router.replace("/dashboard/support", { scroll: false });
  }

  useEffect(() => {
    if (openedInitial.current) return;
    openedInitial.current = true;
    if (initialDmId) void openDmById(initialDmId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialDmId]);

  // Poll for a staff reply while a thread is open — same reasoning as the
  // ticket tab's own poll (no revalidatePath reaches this client-held
  // thread), just without the "staff is typing" layer on top.
  useEffect(() => {
    if (!openDm) return;
    const id = openDm.id;
    const t = setInterval(() => void refreshOpenDm(id), 4000);
    return () => clearInterval(t);
  }, [openDm?.id]);

  return (
    <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_300px]">
      <Panel title={openDm ? undefined : "Messages from Nxeon staff"} sub={openDm ? undefined : `${dms.length} conversation${dms.length === 1 ? "" : "s"}`}>
        {loading ? (
          <div className="flex items-center justify-center py-10">
            <span className="h-6 w-6 animate-spin rounded-full border-2 border-rim-hi border-t-cyan" />
          </div>
        ) : err ? (
          <div className="flex flex-col items-center gap-2 py-8 text-center">
            <span className="text-[13px] font-bold text-white">{err}</span>
            <button type="button" onClick={backToList} className="btn-ghost h-[32px] px-3 text-[12px]">
              ← Back to messages
            </button>
          </div>
        ) : openDm ? (
          <DmThreadPanel dm={openDm} onBack={backToList} onSent={() => refreshOpenDm(openDm.id)} />
        ) : dms.length === 0 ? (
          <div className="flex flex-col items-center gap-1.5 py-8 text-center">
            <Icon name="chatdots" size={24} className="opacity-60" />
            <span className="text-[13px] font-bold text-white">No messages yet</span>
            <span className="max-w-[40ch] text-[11.8px] leading-[1.5] text-tx-faint">
              If our team reaches out with a quick note, it&apos;ll show up here.
            </span>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[480px] border-collapse text-left">
              <thead>
                <tr className="border-b border-rim-soft text-[10.2px] font-semibold uppercase tracking-[0.10em] text-tx-faint">
                  <th className="py-2.5 pr-3">Subject</th>
                  <th className="py-2.5 pr-3">Status</th>
                  <th className="py-2.5">Last updated</th>
                </tr>
              </thead>
              <tbody>
                {dms.map((dm) => (
                  <tr
                    key={dm.id}
                    onClick={() => openDmById(dm.id)}
                    className="cursor-pointer border-b border-rim-soft/60 last:border-0 hover:bg-[rgba(72,148,255,0.05)]"
                  >
                    <td className="max-w-[320px] py-2.5 pr-3 align-top">
                      <span className="flex items-center gap-1.5">
                        {dm.unreadForCustomer && <span className="h-[6px] w-[6px] flex-none rounded-full bg-cyan" aria-hidden />}
                        <span className="trunc block text-[12.8px] font-semibold text-white">{dm.subject}</span>
                      </span>
                      {dm.preview && <span className="trunc block text-[11.3px] text-tx-faint">{dm.preview}</span>}
                    </td>
                    <td className="py-2.5 pr-3 align-top">
                      <DmStatusPill status={dm.status} />
                    </td>
                    <td className="py-2.5 align-top">
                      <span suppressHydrationWarning className="text-[11px] text-tx-faint">
                        {ago(dm.updatedAt)}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Panel>

      <Panel title="What this is">
        <span className="text-[11.8px] leading-[1.5] text-tx-mute">
          A direct note from our team — usually a quick heads-up or a follow-up on something we
          noticed. It&apos;s not a support ticket, so it won&apos;t show up in your ticket history, but
          you can reply right here and we&apos;ll see it.
        </span>
      </Panel>
    </div>
  );
}

function DmThreadPanel({ dm, onBack, onSent }: { dm: StaffDmThread; onBack: () => void; onSent: () => void }) {
  const closed = dm.status === "CLOSED";
  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center gap-2 border-b border-rim-soft pb-3">
        <button type="button" onClick={onBack} className="btn-ghost h-[30px] px-2 text-[12px]">
          ← Back
        </button>
        <span className="flex-1 truncate text-[13.5px] font-bold text-white">{dm.subject}</span>
        <DmStatusPill status={dm.status} />
      </div>

      <div className="max-h-[420px] space-y-3 overflow-y-auto pr-1">
        {dm.messages.map((m) => (
          <div key={m.id} className={`flex ${m.isStaff ? "justify-start" : "justify-end"}`}>
            <div
              className={
                "max-w-[85%] rounded-2xl px-4 py-3 text-[13px] " +
                (m.isStaff ? "border border-white/[0.08] bg-white/[0.04]" : "border border-cyan/30 bg-cyan/10")
              }
            >
              <div className="mb-1 flex items-center gap-2 text-[11px] text-tx-faint">
                <span className="font-semibold text-slate-200">{m.isStaff ? "Nxeon staff" : "You"}</span>
                <span suppressHydrationWarning>{ago(m.createdAt)}</span>
              </div>
              {m.body && <p className="whitespace-pre-wrap leading-relaxed">{m.body}</p>}
            </div>
          </div>
        ))}
      </div>

      {closed ? (
        <p className="text-[12px] text-tx-faint">This conversation is closed.</p>
      ) : (
        <DmReplyForm dmId={dm.id} onSent={onSent} />
      )}
    </div>
  );
}

